CREATE TABLE public.autumn_trees (id text PRIMARY KEY, map_id text NOT NULL, x real NOT NULL, y real NOT NULL);
GRANT SELECT ON public.autumn_trees TO authenticated; GRANT ALL ON public.autumn_trees TO service_role;
ALTER TABLE public.autumn_trees ENABLE ROW LEVEL SECURITY; CREATE POLICY autumn_trees_read ON public.autumn_trees FOR SELECT TO authenticated USING(true);
CREATE TABLE public.autumn_inventory (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, bags integer NOT NULL DEFAULT 0 CHECK(bags>=0), last_push_at timestamptz);
GRANT SELECT ON public.autumn_inventory TO authenticated; GRANT ALL ON public.autumn_inventory TO service_role;
ALTER TABLE public.autumn_inventory ENABLE ROW LEVEL SECURITY; CREATE POLICY autumn_inventory_read ON public.autumn_inventory FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.autumn_rewards (user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, reward_id text NOT NULL CHECK(reward_id IN ('hat_autumn_1','hat_autumn_2','hat_autumn_3','hat_autumn_4','hat_autumn_5','hat_autumn_6','hat_autumn_7','hat_autumn_8','hat_autumn_9','hat_autumn_10','hat_autumn_11','hat_autumn_12','hat_autumn_13','hat_autumn_14','hat_autumn_15','hat_autumn_16','hat_autumn_17','hat_autumn_18','gun_acorn','gun_maple')), qty integer NOT NULL DEFAULT 1 CHECK(qty>0), PRIMARY KEY(user_id,reward_id));
GRANT SELECT ON public.autumn_rewards TO authenticated; GRANT ALL ON public.autumn_rewards TO service_role;
ALTER TABLE public.autumn_rewards ENABLE ROW LEVEL SECURITY; CREATE POLICY autumn_rewards_read ON public.autumn_rewards FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.equip_firearm(_gun text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=public.require_uid(); BEGIN PERFORM public.ensure_firearms(); IF _gun NOT IN ('fists','gun_crystal','gun_pulse','gun_carbine') AND NOT EXISTS(SELECT 1 FROM public.player_art WHERE 'custom:'||id::text=_gun AND user_id=uid AND kind='melee') AND NOT EXISTS(SELECT 1 FROM public.autumn_rewards WHERE user_id=uid AND reward_id=_gun AND reward_id IN ('gun_acorn','gun_maple')) THEN RAISE EXCEPTION 'Todavía no tienes esta arma'; END IF; UPDATE public.player_firearms SET gun_id=_gun WHERE user_id=uid; END $$;
REVOKE ALL ON FUNCTION public.equip_firearm(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.equip_firearm(text) TO authenticated,service_role;
CREATE FUNCTION public.push_autumn_tree(_tree text, _aim text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=public.require_uid(); p public.player_positions; t public.autumn_trees; inv public.autumn_inventory; dropped boolean; dx real; dy real; f real; s real; BEGIN
IF _aim IS NULL OR _aim NOT IN ('up','down','left','right') THEN RAISE EXCEPTION 'Dirección inválida'; END IF;
PERFORM 1 FROM public.player_firearms WHERE user_id=uid AND gun_id='fists' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Selecciona el puño'; END IF;
SELECT * INTO p FROM public.player_positions WHERE user_id=uid; SELECT * INTO t FROM public.autumn_trees WHERE id=_tree;
IF t.id IS NULL OR p.user_id IS NULL OR p.map_id<>t.map_id OR p.updated_at<now()-interval '4 seconds' THEN RAISE EXCEPTION 'Acércate al árbol'; END IF;
dx:=t.x-p.x; dy:=t.y-p.y; f:=CASE _aim WHEN 'up' THEN -dy WHEN 'down' THEN dy WHEN 'left' THEN -dx ELSE dx END; s:=CASE WHEN _aim IN ('up','down') THEN abs(dx) ELSE abs(dy) END;
IF dx*dx+dy*dy>1600 OR f<0 OR s>24 THEN RAISE EXCEPTION 'Mira al árbol y acércate'; END IF;
INSERT INTO public.autumn_inventory(user_id) VALUES(uid) ON CONFLICT DO NOTHING; SELECT * INTO inv FROM public.autumn_inventory WHERE user_id=uid FOR UPDATE;
IF inv.last_push_at>now()-interval '3 seconds' THEN RAISE EXCEPTION 'Espera 3 segundos entre empujones'; END IF;
dropped:=random()<0.27; UPDATE public.autumn_inventory SET last_push_at=now(),bags=bags+CASE WHEN dropped THEN 1 ELSE 0 END WHERE user_id=uid; RETURN jsonb_build_object('dropped',dropped,'bags',inv.bags+CASE WHEN dropped THEN 1 ELSE 0 END); END $$;
REVOKE ALL ON FUNCTION public.push_autumn_tree(text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.push_autumn_tree(text,text) TO authenticated,service_role;
CREATE FUNCTION public.open_autumn_bag() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=public.require_uid(); inv public.autumn_inventory; n integer; reward text; BEGIN SELECT * INTO inv FROM public.autumn_inventory WHERE user_id=uid FOR UPDATE; IF inv.user_id IS NULL OR inv.bags<1 THEN RAISE EXCEPTION 'No tienes bolsas de bellotas'; END IF; n:=floor(random()*20)::integer+1; reward:=CASE WHEN n<=18 THEN 'hat_autumn_'||n::text WHEN n=19 THEN 'gun_acorn' ELSE 'gun_maple' END; UPDATE public.autumn_inventory SET bags=bags-1 WHERE user_id=uid; INSERT INTO public.autumn_rewards(user_id,reward_id) VALUES(uid,reward) ON CONFLICT(user_id,reward_id) DO UPDATE SET qty=autumn_rewards.qty+1; RETURN jsonb_build_object('reward',reward,'bags',inv.bags-1); END $$;
REVOKE ALL ON FUNCTION public.open_autumn_bag() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.open_autumn_bag() TO authenticated,service_role;
CREATE FUNCTION public.validate_autumn_hat() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.hat_id LIKE 'hat_autumn_%' AND NOT EXISTS(SELECT 1 FROM public.autumn_rewards WHERE user_id=NEW.id AND reward_id=NEW.hat_id) THEN RAISE EXCEPTION 'Consigue este hat abriendo una bolsa'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.validate_autumn_hat() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER enforce_autumn_hat BEFORE INSERT OR UPDATE OF hat_id ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.validate_autumn_hat();
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef(oid) INTO definition FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='resolve_firearm_shot'; definition:=replace(definition,'IF f.rounds=0 THEN','IF f.gun_id=''fists'' THEN RAISE EXCEPTION ''El puño no dispara''; END IF; IF f.rounds=0 THEN'); EXECUTE definition; END $$;